// === Tab: mySketch ===
let particles = []; 

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  colorMode(HSB, 360, 100, 100, 200);
  noStroke();

  for (let i = 0; i < 1500; i++) {
    addParticle(true); 
  }
}

function draw() {
  background(0);

  // [最適化2] ループ内で毎回計算していた値を、ループの前に1度だけ計算する
  const timeForNoise = frameCount * 0.01;
  const timeForRotation = frameCount;

  // [最適化1] 生き残ったパーティクルを格納するための新しい配列を用意
  let nextParticles = [];

  for (let i = 0; i < particles.length; i++) { // 逆順ループである必要がなくなった
    let p = particles[i];
    p.y -= p.riseSpeed;

    // [最適化1] 画面外に出たパーティクルは新しい配列に追加せず、ここで処理を終了
    if (p.y + (p.h * map(p.y, height / 2, -height / 2, 1, 0.05) * map(abs(p.x), 0, width / 2, 1, 0.2)) < -height / 2) {
      continue; // 次のパーティクルの処理へ
    }

    // 生き残ったパーティクルは新しい配列に追加する
    nextParticles.push(p);

    let yScaleFactor = map(p.y, height / 2, -height / 2, 1, 0.05);
    let xScaleFactor = map(abs(p.x), 0, width / 2, 1, 0.2);

    let w = p.w * yScaleFactor * xScaleFactor;
    let h = p.h * yScaleFactor * xScaleFactor;

    let baseHue = map(p.y, height / 2, -height / 2, 40, 0);
    let finalHue = baseHue + p.hueOffset;

    // [最適化2] 事前に計算した値を使用
    let flicker = noise(timeForNoise + p.offset) * 20 - 10;

    push();
    translate(p.x + flicker, p.y, p.z);

    // [最適化2] 事前に計算した値を使用
    rotateX(p.rotationX + timeForRotation * p.rotationSpeedX);
    rotateY(p.rotationY + timeForRotation * p.rotationSpeedY);
    rotateZ(p.rotationZ + timeForRotation * p.rotationSpeedZ);

    emissiveMaterial(finalHue, 100, 100, p.alpha);

    plane(w*2, h*2);

    pop();
  }

  // [最適化1] 配列を、生き残ったパーティクルのリストで一括置換する
  particles = nextParticles;

  // 足りなくなったパーティクルを補充する処理は変更なし
  while (particles.length < 1500) {
    addParticle(false);
  }
}

// パーティクルを追加する関数 (変更なし)
function addParticle(isInitial) {
  let x = random(-width / 2, width / 2);
  let y = isInitial ? random(height / 2, -height / 2) : height / 2 + random(50, 100);
  let z = random(-200, 200);
  let w = map(y, height / 2, -height / 2, 50, 5);
  let h = map(y, height / 2, -height / 2, 100, 10);
  let alpha = random(10, 80);
  let offset = random(1000);
  let riseSpeed = random(2, 10);
  let hueOffset = random(-5, 5); 
  let rotationX = random(TWO_PI);
  let rotationY = random(TWO_PI);
  let rotationZ = random(TWO_PI);
  let rotationSpeedX = random(-0.01, 0.01);
  let rotationSpeedY = random(-0.01, 0.01);
  let rotationSpeedZ = random(-0.01, 0.01);
  particles.push({ x, y, z, w, h, alpha, offset, riseSpeed, hueOffset, rotationX, rotationY, rotationZ, rotationSpeedX, rotationSpeedY, rotationSpeedZ });
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
